// SUPABASE EXPLORER (100% Supabase, 0% Drive API)
// ═══════════════════════════════════════════
const SupaExplorer = ({ rootFolderId, mob, drive }) => {
  const [currentFolder, setCurrentFolder] = useState(rootFolderId);
  const [breadcrumb, setBreadcrumb] = useState([{ id: rootFolderId, name: "Inicio" }]);
  const [subfolders, setSubfolders] = useState([]);
  const [docs, setDocs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [previewFile, setPreviewFile] = useState(null);
  const [galleryImages, setGalleryImages] = useState(null);
  const [galleryStart, setGalleryStart] = useState(0);

  useEffect(() => { setCurrentFolder(rootFolderId); setBreadcrumb([{ id: rootFolderId, name: "Inicio" }]); }, [rootFolderId]);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const [folders, files] = await Promise.all([
          supaFetch("drive_folders", { filters: `parent_drive_id=eq.${currentFolder}`, order: "name" }),
          supaFetch("documents", { filters: `parent_folder_drive_id=eq.${currentFolder}`, order: "title" }),
        ]);
        setSubfolders(folders || []);
        setDocs(files || []);
      } catch (e) { console.error(e); setSubfolders([]); setDocs([]); }
      setLoading(false);
    };
    load();
  }, [currentFolder]);

  const navigateToFolder = (driveId, folderName) => {
    setCurrentFolder(driveId);
    setBreadcrumb(prev => [...prev, { id: driveId, name: folderName }]);
  };
  const navigateToBreadcrumb = (index) => {
    setCurrentFolder(breadcrumb[index].id);
    setBreadcrumb(breadcrumb.slice(0, index + 1));
  };

  const imageFiles = docs.filter(d => isImage(d.mime_type));
  const nonImageFiles = docs.filter(d => !isImage(d.mime_type));

  const openImage = (imgDoc, idx) => {
    setGalleryImages(imageFiles);
    setGalleryStart(idx);
  };

  return (
    <div>
      {/* Photo gallery */}
      {galleryImages && (
        <PhotoGallery images={galleryImages} startIndex={galleryStart} onClose={() => setGalleryImages(null)} mob={mob} token={drive?.token} />
      )}

      {/* File preview modal (non-image) */}
      {previewFile && (
        <>
          <div onClick={() => setPreviewFile(null)} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.85)", zIndex: 9999 }} />
          <div style={{ position: "fixed", top: mob ? "2%" : "5%", left: mob ? "2%" : "10%", right: mob ? "2%" : "10%", bottom: mob ? "2%" : "5%", zIndex: 10000, display: "flex", flexDirection: "column", background: C.surface, borderRadius: 16, border: `1px solid ${C.accent}40`, overflow: "hidden" }}>
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 16px", borderBottom: `1px solid ${C.border}` }}>
              <span style={{ fontFamily: "DM Sans", fontSize: 14, fontWeight: 600, color: C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", flex: 1 }}>{previewFile.name}</span>
              <div style={{ display: "flex", gap: 8, flexShrink: 0 }}>
                <a href={`https://drive.google.com/file/d/${previewFile.id}/view`} target="_blank" rel="noopener" style={{ fontFamily: "DM Sans", fontSize: 12, color: C.blue, textDecoration: "none", padding: "4px 10px", border: `1px solid ${C.border}`, borderRadius: 6 }}>Abrir en Drive ↗</a>
                <button onClick={() => setPreviewFile(null)} style={{ background: "none", border: "none", cursor: "pointer", color: C.textDim, display: "flex", padding: 4 }}>{I.close}</button>
              </div>
            </div>
            <iframe src={getPreviewUrl(previewFile.id)} style={{ flex: 1, border: "none", background: "#fff" }} allow="autoplay" sandbox="allow-same-origin allow-scripts allow-popups allow-forms" />
          </div>
        </>
      )}

      {/* Breadcrumb */}
      {breadcrumb.length > 1 && (
        <div style={{ display: "flex", alignItems: "center", gap: 4, marginBottom: 12, flexWrap: "wrap" }}>
          {breadcrumb.map((b, i) => (
            <span key={i} style={{ display: "flex", alignItems: "center", gap: 4 }}>
              {i > 0 && <span style={{ color: C.textMuted, fontSize: 12 }}>/</span>}
              <button onClick={() => navigateToBreadcrumb(i)} style={{ background: "none", border: "none", cursor: "pointer", fontFamily: "DM Sans", fontSize: 13, color: i === breadcrumb.length - 1 ? C.accent : C.textDim, fontWeight: i === breadcrumb.length - 1 ? 600 : 400, padding: "2px 4px" }}>{b.name}</button>
            </span>
          ))}
        </div>
      )}

      <Card>
        {loading ? (
          <div style={{ textAlign: "center", padding: 30 }}><Spinner /><p style={{ fontFamily: "DM Sans", fontSize: 13, color: C.textDim, marginTop: 12 }}>Cargando...</p></div>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
            {breadcrumb.length > 1 && (
              <button onClick={() => navigateToBreadcrumb(breadcrumb.length - 2)} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", background: "transparent", border: "none", cursor: "pointer", borderRadius: 8, width: "100%" }}
                onMouseEnter={e => e.currentTarget.style.background = C.surface2} onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                {I.back}<span style={{ fontFamily: "DM Sans", fontSize: 14, color: C.textDim }}>.. Regresar</span>
              </button>
            )}
            {subfolders.map(f => (
              <button key={f.id} onClick={() => navigateToFolder(f.google_drive_id, f.name)} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", background: "transparent", border: "none", cursor: "pointer", borderRadius: 8, width: "100%", textAlign: "left" }}
                onMouseEnter={e => e.currentTarget.style.background = C.surface2} onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                <span style={{ color: C.accent }}>{I.folder}</span>
                <span style={{ fontFamily: "DM Sans", fontSize: 14, fontWeight: 500, color: C.text, flex: 1 }}>{f.name}</span>
                <span style={{ fontFamily: "DM Sans", fontSize: 12, color: C.textMuted }}>Carpeta</span>
              </button>
            ))}
            {nonImageFiles.map(d => (
              <button key={d.id} onClick={() => d.google_drive_file_id && setPreviewFile({ id: d.google_drive_file_id, name: d.title })} style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 14px", borderRadius: 8, width: "100%", background: "transparent", border: "none", cursor: "pointer", textAlign: "left" }}
                onMouseEnter={e => e.currentTarget.style.background = C.surface2} onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                <span style={{ fontSize: 16 }}>{getFileIcon(d.mime_type)}</span>
                <span style={{ fontFamily: "DM Sans", fontSize: 14, color: C.text, flex: 1 }}>{d.title}</span>
                <Badge color={C.blue}>{d.file_type || getFileExt(d.mime_type) || "file"}</Badge>
              </button>
            ))}
            {/* Image grid with gallery */}
            {imageFiles.length > 0 && (
              <div style={{ padding: "12px 0 4px" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8, paddingLeft: 4 }}>
                  <span style={{ fontFamily: "DM Sans", fontSize: 12, color: C.textDim }}>🖼️ {imageFiles.length} fotos</span>
                  {!drive?.token && drive?.signIn && (
                    <button onClick={drive.signIn} style={{
                      fontFamily: "DM Sans", fontSize: 11, color: C.blue, background: `${C.blue}15`,
                      border: `1px solid ${C.blue}40`, borderRadius: 6, padding: "3px 10px", cursor: "pointer",
                    }}>Conectar Drive para ver fotos</button>
                  )}
                </div>
                <div style={{ display: "grid", gridTemplateColumns: mob ? "repeat(3, 1fr)" : "repeat(4, 1fr)", gap: 6 }}>
                  {imageFiles.map((img, idx) => (
                    <button key={img.id} onClick={() => openImage(img, idx)} style={{
                      background: C.surface2, border: `1px solid ${C.border}`, borderRadius: 8,
                      cursor: "pointer", overflow: "hidden", aspectRatio: "1", display: "flex",
                      alignItems: "center", justifyContent: "center", padding: 0, transition: "border-color 0.2s",
                    }}
                      onMouseEnter={e => e.currentTarget.style.borderColor = C.accent}
                      onMouseLeave={e => e.currentTarget.style.borderColor = C.border}>
                      {drive?.token ? (
                        <AuthImage fileId={img.google_drive_file_id} token={drive.token} alt={img.title}
                          style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                      ) : (
                        <span style={{ fontSize: 24 }}>📷</span>
                      )}
                    </button>
                  ))}
                </div>
              </div>
            )}
            {subfolders.length === 0 && docs.length === 0 && !loading && (
              <div style={{ textAlign: "center", padding: 30 }}><p style={{ fontFamily: "DM Sans", fontSize: 14, color: C.textDim }}>Carpeta vacía</p></div>
            )}
          </div>
        )}
      </Card>
      <div style={{ fontFamily: "DM Sans", fontSize: 12, color: C.textMuted, marginTop: 8 }}>{subfolders.length} carpetas, {docs.length} archivos</div>
    </div>
  );
};

// ─── House icon ───
const HouseIcon = () => (
  <svg width="22" height="22" fill="none" stroke="currentColor" strokeWidth="1.8" viewBox="0 0 24 24">
    <path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/><polyline points="9,22 9,12 15,12 15,22"/>
  </svg>
);

// ═══════════════════════════════════════════
// PROPERTIES VIEW (con sort por # o calle)
// ═══════════════════════════════════════════
// ═══════════════════════════════════════════
// DROPDOWN MENU (reusable)
// ═══════════════════════════════════════════
const DropMenu = ({ open, onClose, children, style }) => {
  const menuRef = useRef(null);
  useEffect(() => {
    if (!open) return;
    const handler = (e) => { if (menuRef.current && !menuRef.current.contains(e.target)) onClose(); };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [open]);
  if (!open) return null;
  return (
    <div ref={menuRef} style={{
      position: "absolute", right: 0, top: "100%", marginTop: 6, background: C.surface,
      border: `1px solid ${C.border}`, borderRadius: 12, boxShadow: "0 8px 30px rgba(0,0,0,0.4)",
      minWidth: 200, zIndex: 100, overflow: "hidden", ...style,
    }}>{children}</div>
  );
};
const MenuBtn = ({ onClick, children, active }) => (
  <button onClick={onClick} style={{
    width: "100%", textAlign: "left", padding: "10px 16px",
    background: active ? C.accentGlow : "transparent", border: "none", cursor: "pointer",
    fontFamily: "DM Sans", fontSize: 13, color: active ? C.accent : C.text, display: "flex", alignItems: "center", gap: 8,
  }}
    onMouseEnter={e => e.currentTarget.style.background = C.surface2}
    onMouseLeave={e => e.currentTarget.style.background = active ? C.accentGlow : "transparent"}
  >{children}</button>
);
const MenuDivider = () => <div style={{ height: 1, background: C.border, margin: "4px 0" }} />;
const MenuLabel = ({ children }) => <div style={{ padding: "8px 16px 4px", fontFamily: "DM Sans", fontSize: 11, fontWeight: 600, color: C.textDim, textTransform: "uppercase", letterSpacing: 0.5 }}>{children}</div>;
const HamburgerBtn = ({ open, onClick }) => (
  <button onClick={onClick} style={{
    background: open ? C.accentGlow : "none", border: `1px solid ${open ? C.accent : C.border}`,
    cursor: "pointer", padding: "8px 10px", borderRadius: 8, color: open ? C.accent : C.text, display: "flex", alignItems: "center",
  }}><svg width="20" height="20" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button>
);

// ═══════════════════════════════════════════
// PROPERTIES VIEW (con sort y hamburger menu)
// ═══════════════════════════════════════════
const PropertiesView = ({ mob, drive, onSelectProperty, onBack }) => {
  const [filter, setFilter] = useState("all");
  const [sortBy, setSortBy] = useState("number");
  const [menuOpen, setMenuOpen] = useState(false);
  const [uploadTarget, setUploadTarget] = useState(null); // property for upload
  const [uploading, setUploading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState("");
  const fileInputRef = useRef(null);

  const owners = [...new Set(PROPERTIES.map(p => p.owner))];
  let filtered = filter === "all" ? [...PROPERTIES] : PROPERTIES.filter(p => p.owner === filter);
  if (sortBy === "number") filtered.sort((a, b) => getNumber(a.address) - getNumber(b.address));
  else filtered.sort((a, b) => getStreet(a.address).localeCompare(getStreet(b.address)));

  const handleStartUpload = (prop) => {
    setUploadTarget(prop);
    setMenuOpen(false);
    if (!drive?.token && drive?.signIn) { drive.signIn(); return; }
    setTimeout(() => fileInputRef.current?.click(), 100);
  };

  const handleFilesSelected = async (e) => {
    const files = Array.from(e.target.files || []);
    if (!files.length || !drive?.token || !drive?.uploadPhotos || !uploadTarget) return;

    // Find folder ID for this property
    setUploading(true); setUploadMsg(`Buscando carpeta de ${uploadTarget.address}...`);
    const folder = await findFolderByAddress(uploadTarget.address);
    if (!folder) {
      setUploadMsg("No se encontró la carpeta. Vincula manualmente primero.");
      setUploading(false); return;
    }

    setUploadMsg(`Subiendo ${files.length} fotos...`);
    try {
      const { results } = await drive.uploadPhotos(
        files, folder.google_drive_id, uploadTarget.address,
        (i, total, name) => setUploadMsg(`Subiendo ${i}/${total}: ${name}`)
      );
      setUploadMsg(`✓ ${results.length} fotos subidas a ${uploadTarget.address}`);
      setTimeout(() => setUploadMsg(""), 6000);
    } catch (err) {
      setUploadMsg(`Error: ${err.message}`);
    }
    setUploading(false); setUploadTarget(null);
    e.target.value = "";
  };

  return (
    <div>
      <input ref={fileInputRef} type="file" accept="image/*" multiple onChange={handleFilesSelected} style={{ display: "none" }} />

      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", color: C.textDim, display: "flex", padding: 4 }}>{I.back}</button>
        <span style={{ color: C.accent }}><HouseIcon /></span>
        <h1 style={{ fontFamily: "DM Sans", fontSize: mob ? 20 : 24, fontWeight: 700, color: C.accent, flex: 1 }}>Propiedades</h1>
        <Badge color={C.textDim}>{PROPERTIES.length}</Badge>
        <div style={{ position: "relative" }}>
          <HamburgerBtn open={menuOpen} onClick={() => setMenuOpen(!menuOpen)} />
          <DropMenu open={menuOpen} onClose={() => setMenuOpen(false)}>
            <MenuLabel>Ordenar</MenuLabel>
            <MenuBtn onClick={() => { setSortBy("number"); setMenuOpen(false); }} active={sortBy === "number"}>
              # Número {sortBy === "number" && "✓"}
            </MenuBtn>
            <MenuBtn onClick={() => { setSortBy("street"); setMenuOpen(false); }} active={sortBy === "street"}>
              🏠 Calle {sortBy === "street" && "✓"}
            </MenuBtn>
            <MenuDivider />
            <MenuLabel>Fotos</MenuLabel>
            <MenuBtn onClick={() => {
              if (!drive?.token && drive?.signIn) { drive.signIn(); setMenuOpen(false); return; }
              setMenuOpen(false);
            }}>
              {drive?.token ? "✅ Drive conectado" : "🔗 Conectar Google Drive"}
            </MenuBtn>
          </DropMenu>
        </div>
      </div>

      {/* Upload status */}
      {uploadMsg && (
        <div style={{ padding: "8px 14px", marginBottom: 12, borderRadius: 8, background: uploadMsg.startsWith("✓") ? `${C.green}15` : `${C.accent}15`, border: `1px solid ${uploadMsg.startsWith("✓") ? C.green : C.accent}40` }}>
          <span style={{ fontFamily: "DM Sans", fontSize: 12, color: uploadMsg.startsWith("✓") ? C.green : uploadMsg.startsWith("Error") ? C.red : C.accent }}>{uploadMsg}</span>
        </div>
      )}

      {/* Filter chips */}
      <div style={{ display: "flex", gap: 6, marginBottom: 16, flexWrap: "wrap" }}>
        <button onClick={() => setFilter("all")} style={{
          padding: "5px 14px", borderRadius: 20, border: `1px solid ${filter === "all" ? C.accent : C.border}`,
          background: filter === "all" ? C.accentGlow : "transparent", cursor: "pointer",
          fontFamily: "DM Sans", fontSize: 12, fontWeight: 500, color: filter === "all" ? C.accent : C.textDim,
        }}>Todas ({PROPERTIES.length})</button>
        {owners.map(o => {
          const count = PROPERTIES.filter(p => p.owner === o).length;
          const color = OWNER_COLORS[o] || C.textDim;
          return (
            <button key={o} onClick={() => setFilter(o)} style={{
              padding: "5px 14px", borderRadius: 20, border: `1px solid ${filter === o ? color : C.border}`,
              background: filter === o ? `${color}18` : "transparent", cursor: "pointer",
              fontFamily: "DM Sans", fontSize: 12, fontWeight: 500, color: filter === o ? color : C.textDim,
            }}>{(OWNER_SHORT[o] || o)} ({count})</button>
          );
        })}
      </div>

      <Card>
        <div style={{ display: "flex", flexDirection: "column", gap: 2 }}>
          {filtered.map((prop, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <button onClick={() => onSelectProperty(prop)} style={{
                display: "flex", alignItems: "center", gap: 12, padding: "12px 14px",
                background: "transparent", border: "none", cursor: "pointer", borderRadius: 8,
                flex: 1, textAlign: "left",
              }}
                onMouseEnter={e => e.currentTarget.style.background = C.surface2}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                <span style={{ color: OWNER_COLORS[prop.owner] || C.textDim }}><HouseIcon /></span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: "DM Sans", fontSize: 14, fontWeight: 500, color: C.text }}>{prop.address}</div>
                </div>
                <Badge color={OWNER_COLORS[prop.owner] || C.textDim}>{OWNER_SHORT[prop.owner] || prop.owner}</Badge>
              </button>
              {/* Upload button per property */}
              <button onClick={() => handleStartUpload(prop)} disabled={uploading} title="Subir fotos" style={{
                background: "none", border: "none", cursor: uploading ? "default" : "pointer",
                padding: "8px", borderRadius: 6, color: C.textDim, fontSize: 16, flexShrink: 0, opacity: uploading ? 0.3 : 1,
              }}
                onMouseEnter={e => e.currentTarget.style.background = C.surface2}
                onMouseLeave={e => e.currentTarget.style.background = "transparent"}>
                📸
              </button>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
};

// ═══════════════════════════════════════════
// PROPERTY EXPENSES
// ═══════════════════════════════════════════
const PropertyExpenses = ({ address, mob }) => {
  const [propExp, setPropExp] = useState([]);
  const [dailyExp, setDailyExp] = useState([]);
  const [loading, setLoading] = useState(true);
  const [adding, setAdding] = useState(false);
  const [addType, setAddType] = useState("electricity");
  const [addMonth, setAddMonth] = useState(new Date().getMonth() + 1);
  const [addYear, setAddYear] = useState(new Date().getFullYear());
  const [addAmount, setAddAmount] = useState("");
  const [addNotes, setAddNotes] = useState("");
  const [saving, setSaving] = useState(false);
  const [viewType, setViewType] = useState(null);
  const [viewMonth, setViewMonth] = useState(null); // { month, year }

  const types = getPropExpenseTypes(address);

  // Map tags → property address + expense type
  const TAG_MAP = {
    "Argo - Agua/Gas": { addr: "232 Argo Avenue", types: ["water", "gas"] },
    "Argo - Luz": { addr: "232 Argo Avenue", types: ["electricity"] },
    "Argo - Mant.": { addr: "232 Argo Avenue", types: ["hoa"] },
    "Progreso - Luz": { addr: "Ave Progreso 15, Depto C101", types: ["electricity"] },
    "Progreso - Agua": { addr: "Ave Progreso 15, Depto C101", types: ["water"] },
  };

  // Find tags for this property
  const myTags = Object.entries(TAG_MAP).filter(([, v]) => v.addr === address).map(([tag]) => tag);
  // Also match by owner for US properties
  const ownerTags = ["Mango Nest", "MNA Works", "Tortuga Home"];

  const tagToType = (tag) => {
    const m = TAG_MAP[tag];
    if (m) return m.types[0]; // primary type
    return "hoa"; // owner-based tags → generic
  };

  const loadData = async () => {
    setLoading(true);
    // 1. Structured property expenses
    const pe = await supaFetch("property_expenses", {
      filters: `property_address=eq.${encodeURIComponent(address)}`,
      order: "period_year.desc,period_month.desc",
    });
    setPropExp(pe || []);

    // 2. Daily expenses with matching tags
    if (myTags.length > 0) {
      const tagFilter = myTags.map(t => `tag.eq.${encodeURIComponent(t)}`).join(",");
      const de = await supaFetch("daily_expenses", {
        filters: `or=(${tagFilter})`,
        order: "expense_date.desc",
      });
      setDailyExp(de || []);
    } else {
      // For US properties, match by owner tag
      const prop = PROPERTIES.find(p => p.address === address);
      if (prop && ownerTags.includes(prop.owner)) {
        const de = await supaFetch("daily_expenses", {
          filters: `tag=eq.${encodeURIComponent(prop.owner)}`,
          order: "expense_date.desc",
        });
        setDailyExp(de || []);
      } else {
        setDailyExp([]);
      }
    }
    setLoading(false);
  };
  useEffect(() => { loadData(); }, [address]);

  // Normalize daily_expenses into same shape
  const normalizedDaily = dailyExp.map(e => {
    const d = new Date(e.expense_date + "T00:00:00");
    return {
      id: e.id, source: "daily", expense_type: tagToType(e.tag),
      amount: Number(e.amount), period_month: d.getMonth() + 1, period_year: d.getFullYear(),
      notes: e.concept, date: e.expense_date, tag: e.tag, subcategory: e.subcategory,
    };
  });

  const normalizedProp = propExp.map(e => ({
    ...e, source: "property", date: null,
  }));

  const allExpenses = [...normalizedProp, ...normalizedDaily];

  const handleAdd = async () => {
    setSaving(true);
    await supaInsert("property_expenses", {
      property_address: address, expense_type: addType,
      amount: parseFloat(addAmount) || 0, period_month: addMonth,
      period_year: addYear, notes: addNotes || null, paid: true,
    });
    await loadData();
    setAdding(false); setSaving(false); setAddAmount(""); setAddNotes("");
  };

  const handleDelete = async (item) => {
    if (item.source === "property") await supaDelete("property_expenses", item.id);
    // Don't delete daily_expenses from here
    await loadData();
  };

  if (loading) return <Card><div style={{ textAlign: "center", padding: 20 }}><Spinner /></div></Card>;

  const totalAll = allExpenses.reduce((s, e) => s + Number(e.amount || 0), 0);

  // ── LEVEL 2: Month detail ──
  if (viewType && viewMonth) {
    const items = allExpenses.filter(e => e.expense_type === viewType && e.period_month === viewMonth.month && e.period_year === viewMonth.year);
    const ti = types.find(t => t.key === viewType);
    return (
      <Card style={{ marginBottom: 16 }}>
        <button onClick={() => setViewMonth(null)} style={{ background: "none", border: "none", cursor: "pointer", fontFamily: "DM Sans", fontSize: 14, fontWeight: 600, color: C.accent, padding: 0, marginBottom: 12 }}>
          ← {ti?.icon} {ti?.label} · {MONTHS_SHORT[viewMonth.month - 1]} {viewMonth.year}
        </button>
        <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
          {items.map((e, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 10px", background: C.surface2, borderRadius: 6 }}>
              <span style={{ fontSize: 10, color: e.source === "daily" ? "#A78BFA" : "#22C55E" }}>{e.source === "daily" ? "📋" : "📝"}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontFamily: "DM Sans", fontSize: 12, color: C.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{e.notes || "—"}</div>
                {e.date && <div style={{ fontFamily: "DM Sans", fontSize: 10, color: C.textMuted }}>{e.date}</div>}
                {e.tag && <div style={{ fontFamily: "DM Sans", fontSize: 10, color: "#A78BFA" }}>{e.tag}{e.subcategory ? ` · ${e.subcategory}` : ""}</div>}
              </div>
              <span style={{ fontFamily: "JetBrains Mono", fontSize: 13, fontWeight: 500, color: C.text, whiteSpace: "nowrap" }}>{fmtMoney(e.amount)}</span>
              {e.source === "property" && <button onClick={() => handleDelete(e)} style={{ background: "none", border: "none", cursor: "pointer", color: C.textMuted, fontSize: 12, padding: "2px 4px" }}>✕</button>}
            </div>
          ))}
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", padding: "8px 10px" }}>
          <span style={{ fontFamily: "JetBrains Mono", fontSize: 12, fontWeight: 600, color: C.accent }}>Total: {fmtMoney(items.reduce((s, e) => s + Number(e.amount || 0), 0))}</span>
        </div>
      </Card>
    );
  }

  // ── LEVEL 1: Type detail (months) ──
  if (viewType) {
    const items = allExpenses.filter(e => e.expense_type === viewType);
    const ti = types.find(t => t.key === viewType);
    // Group by year+month
    const grouped = {};
    items.forEach(e => {
      const key = `${e.period_year}-${String(e.period_month).padStart(2, "0")}`;
      if (!grouped[key]) grouped[key] = { year: e.period_year, month: e.period_month, items: [], total: 0 };
      grouped[key].items.push(e);
      grouped[key].total += Number(e.amount || 0);
    });
    const months = Object.values(grouped).sort((a, b) => b.year - a.year || b.month - a.month);
    const years = [...new Set(months.map(m => m.year))].sort((a, b) => b - a);

    return (
      <Card style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
          <button onClick={() => setViewType(null)} style={{ background: "none", border: "none", cursor: "pointer", fontFamily: "DM Sans", fontSize: 14, fontWeight: 600, color: C.accent, padding: 0 }}>
            ← {ti?.icon} {ti?.label}
          </button>
          <Badge color={C.textDim}>{items.length} pagos</Badge>
        </div>
        {years.map(year => {
          const ym = months.filter(m => m.year === year);
          const yearTotal = ym.reduce((s, m) => s + m.total, 0);
          return (
            <div key={year} style={{ marginBottom: 12 }}>
              <div style={{ fontFamily: "DM Sans", fontSize: 12, fontWeight: 600, color: C.textDim, marginBottom: 6 }}>{year}</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                {ym.map(m => (
                  <button key={`${m.year}-${m.month}`} onClick={() => setViewMonth({ month: m.month, year: m.year })} style={{
                    display: "flex", alignItems: "center", gap: 8, padding: "8px 10px",
                    background: C.surface2, borderRadius: 6, border: "none", cursor: "pointer", width: "100%", textAlign: "left",
                  }}
                    onMouseEnter={e => e.currentTarget.style.background = C.accentGlow}
                    onMouseLeave={e => e.currentTarget.style.background = C.surface2}>
                    <span style={{ fontFamily: "DM Sans", fontSize: 12, color: C.textDim, width: 30 }}>{MONTHS_SHORT[m.month - 1]}</span>
                    <span style={{ fontFamily: "JetBrains Mono", fontSize: 13, color: C.text, flex: 1 }}>{fmtMoney(m.total)}</span>
                    <span style={{ fontFamily: "DM Sans", fontSize: 10, color: C.textMuted }}>{m.items.length} item{m.items.length > 1 ? "s" : ""}</span>
                    <span style={{ color: C.textMuted, fontSize: 12 }}>▸</span>
                  </button>
                ))}
              </div>
              <div style={{ display: "flex", justifyContent: "flex-end", padding: "4px 10px" }}>
                <span style={{ fontFamily: "JetBrains Mono", fontSize: 12, color: C.accent }}>Subtotal: {fmtMoney(yearTotal)}</span>
              </div>
            </div>
          );
        })}
        <div style={{ display: "flex", justifyContent: "flex-end", padding: "8px 10px", borderTop: `1px solid ${C.border}`, marginTop: 4 }}>
          <span style={{ fontFamily: "JetBrains Mono", fontSize: 13, fontWeight: 600, color: C.accent }}>Total: {fmtMoney(items.reduce((s, e) => s + Number(e.amount || 0), 0))}</span>
        </div>
      </Card>
    );
  }

  // ── LEVEL 0: Summary ──
  return (
    <Card style={{ marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12 }}>
        <div style={{ fontFamily: "DM Sans", fontSize: 14, fontWeight: 600, color: C.text }}>💰 Gastos de la Propiedad</div>
        <Badge color={C.textDim}>{allExpenses.length} pagos</Badge>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: mob ? "1fr 1fr" : "1fr 1fr 1fr", gap: 8, marginBottom: 12 }}>
        {types.map(t => {
          const items = allExpenses.filter(e => e.expense_type === t.key);
          const total = items.reduce((s, e) => s + Number(e.amount || 0), 0);
          const count = items.length;
          return (
            <button key={t.key} onClick={() => count > 0 && setViewType(t.key)} style={{
              padding: "10px 12px", background: C.surface2, borderRadius: 8,
              border: `1px solid ${C.border}`, cursor: count > 0 ? "pointer" : "default",
              textAlign: "left", opacity: count > 0 ? 1 : 0.5, transition: "border-color 0.2s",
            }}
              onMouseEnter={e => count > 0 && (e.currentTarget.style.borderColor = C.accent)}
              onMouseLeave={e => (e.currentTarget.style.borderColor = C.border)}>
              <div style={{ fontFamily: "DM Sans", fontSize: 12, color: C.textDim }}>{t.icon} {t.label}</div>
              <div style={{ fontFamily: "JetBrains Mono", fontSize: 14, fontWeight: 600, color: count > 0 ? C.text : C.textMuted, marginTop: 4 }}>
                {count > 0 ? fmtMoney(total) : "—"}
              </div>
              {count > 0 && <div style={{ fontFamily: "DM Sans", fontSize: 10, color: C.textMuted, marginTop: 2 }}>{count} pagos</div>}
            </button>
          );
        })}
      </div>

      {allExpenses.length > 0 && (
        <div style={{ display: "flex", justifyContent: "space-between", padding: "8px 12px", background: C.accentGlow, borderRadius: 8, marginBottom: 12 }}>
          <span style={{ fontFamily: "DM Sans", fontSize: 13, fontWeight: 600, color: C.accent }}>Total</span>
          <span style={{ fontFamily: "JetBrains Mono", fontSize: 13, fontWeight: 600, color: C.accent }}>{fmtMoney(totalAll)}</span>
        </div>
      )}

      {dailyExp.length > 0 && (
        <div style={{ fontFamily: "DM Sans", fontSize: 10, color: C.textMuted, marginBottom: 8, textAlign: "center" }}>
          📋 Incluye {dailyExp.length} gastos de Gastos Diarios
        </div>
      )}

      {adding ? (
        <div style={{ padding: "12px", background: C.surface2, borderRadius: 10, border: `1px solid ${C.accent}40` }}>
          <div style={{ fontFamily: "DM Sans", fontSize: 13, fontWeight: 600, color: C.accent, marginBottom: 10 }}>+ Nuevo gasto</div>
          <div style={{ display: "flex", gap: 4, flexWrap: "wrap", marginBottom: 8 }}>
            {types.map(t => (
              <button key={t.key} onClick={() => setAddType(t.key)} style={{
                padding: "3px 10px", borderRadius: 12, border: `1px solid ${addType === t.key ? C.accent : C.border}`,
                background: addType === t.key ? C.accentGlow : "transparent", cursor: "pointer",
                fontFamily: "DM Sans", fontSize: 11, color: addType === t.key ? C.accent : C.textDim,
              }}>{t.icon} {t.label}</button>
            ))}
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 8 }}>
            <select value={addMonth} onChange={e => setAddMonth(parseInt(e.target.value))} style={{ ...dateStyle, padding: "6px 8px" }}>
              {MONTHS_SHORT.map((m, i) => <option key={i} value={i + 1}>{m}</option>)}
            </select>
            <input type="number" value={addYear} onChange={e => setAddYear(parseInt(e.target.value))} style={{ ...dateStyle, width: 70 }} />
            <input type="number" value={addAmount} onChange={e => setAddAmount(e.target.value)} placeholder="Monto" step="0.01" style={{ ...dateStyle, flex: 1, minWidth: 80 }} />
            <input type="text" value={addNotes} onChange={e => setAddNotes(e.target.value)} placeholder="Notas" style={{ ...dateStyle, flex: 1, minWidth: 80 }} />
          </div>
          <div style={{ display: "flex", gap: 6 }}>
            <button onClick={handleAdd} disabled={saving || !addAmount} style={{ fontFamily: "DM Sans", fontSize: 12, padding: "5px 14px", borderRadius: 6, border: "none", background: C.accent, color: "#fff", cursor: "pointer", opacity: !addAmount ? 0.5 : 1 }}>{saving ? "..." : "Agregar"}</button>
            <button onClick={() => setAdding(false)} style={{ fontFamily: "DM Sans", fontSize: 12, padding: "5px 14px", borderRadius: 6, border: `1px solid ${C.border}`, background: "transparent", color: C.textDim, cursor: "pointer" }}>Cancelar</button>
          </div>
        </div>
      ) : (
        <button onClick={() => setAdding(true)} style={{ padding: "8px 14px", background: "transparent", border: `1px dashed ${C.border}`, borderRadius: 8, cursor: "pointer", fontFamily: "DM Sans", fontSize: 12, color: C.textDim, width: "100%", textAlign: "center" }}>+ Agregar gasto</button>
      )}
    </Card>
  );
};

// ═══════════════════════════════════════════
// PROPERTY DETAIL
// ═══════════════════════════════════════════
const PropertyDetail = ({ property, mob, drive, onBack }) => {
  const [folderId, setFolderId] = useState(null);
  const [searching, setSearching] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [showDocs, setShowDocs] = useState(false);

  useEffect(() => {
    setSearching(true); setNotFound(false); setFolderId(null);
    findFolderByAddress(property.address).then(folder => {
      if (folder) setFolderId(folder.google_drive_id);
      else setNotFound(true);
      setSearching(false);
    });
  }, [property.address]);

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16 }}>
        <button onClick={onBack} style={{ background: "none", border: "none", cursor: "pointer", color: C.textDim, display: "flex", padding: 4 }}>{I.back}</button>
        <span style={{ color: OWNER_COLORS[property.owner] || C.accent }}><HouseIcon /></span>
        <div style={{ flex: 1 }}>
          <h1 style={{ fontFamily: "DM Sans", fontSize: mob ? 18 : 22, fontWeight: 700, color: C.text }}>{property.address}</h1>
          <span style={{ fontFamily: "DM Sans", fontSize: 12, color: OWNER_COLORS[property.owner] || C.textDim }}>{property.owner}</span>
        </div>
      </div>

      {/* Property Expenses */}
      <PropertyExpenses address={property.address} mob={mob} />

      {/* Documents toggle */}
      {searching && <Card style={{ textAlign: "center", padding: 30 }}><Spinner /><p style={{ fontFamily: "DM Sans", fontSize: 13, color: C.textDim, marginTop: 12 }}>Buscando carpeta...</p></Card>}
      {notFound && !searching && (
        <Card style={{ textAlign: "center", padding: 30 }}><div style={{ fontSize: 36, marginBottom: 12 }}>📂</div><p style={{ fontFamily: "DM Sans", fontSize: 14, color: C.textDim }}>No se encontró carpeta de Drive</p></Card>
      )}
      {folderId && (
        <>
          <button onClick={() => setShowDocs(!showDocs)} style={{
            display: "flex", alignItems: "center", gap: 8, padding: "10px 16px", marginBottom: 12,
            background: C.surface2, border: `1px solid ${C.border}`, borderRadius: 10,
            cursor: "pointer", width: "100%", fontFamily: "DM Sans", fontSize: 13, fontWeight: 500, color: C.accent,
          }}>
            <span>{showDocs ? "▼" : "▶"}</span>
            <span>📂 Documentos en Drive</span>
          </button>
          {showDocs && <SupaExplorer rootFolderId={folderId} mob={mob} drive={drive} />}
        </>
      )}
    </div>
  );
};

